questions.raw:
{p1:1, s:"Person", g:"p1", core:1, req:1, l:"Zivilstand", k:"civil_status", t:"opts", q:"Und Ihr <b>Zivilstand</b>?",
   why:"Bei unverheirateten Paaren gibt es kein gesetzliches Erbrecht — das ist oft die grösste Lücke im ganzen Plan.",
   opts:["ledig","ledig, mit Partner","verheiratet","eingetragene Partnerschaft","geschieden","verwitwet"]}

{p1:1, s:"Person", core:1, l:"Anzahl Kinder", k:"children_count", t:"num", q:"Wie viele <b>Kinder</b> haben Sie, für die Sie finanziell aufkommen?",
   why:"Kinderkosten sind gebunden und datiert: sie laufen bis zum Ende der Ausbildung und lassen sich nicht kürzen, wenn es eng wird. Das macht sie zu etwas anderem als Konsum.",
   unit:"Kinder", min:0, max:12}

{s:"Person", g:"kids", core:1, dep:"children_count", l:"Jahrgänge der Kinder", k:"children_ages", t:"text", q:"In welchen <b>Jahren</b> sind sie geboren?",
   why:"Damit lässt sich berechnen, wie lange die Kosten noch laufen — und wann sie enden. Ein Kind von neun bindet Sie deutlich länger als eines von neunzehn.",
   onlyIf:d=>Number(d.children_count) > 0}

{s:"Person", core:1, l:"Unterhalt", k:"alimony_direction", t:"opts", q:"Zahlen oder erhalten Sie <b>Unterhalt</b>?",
   why:"Unterhalt ist die am häufigsten vergessene Position im ganzen Fragebogen — und eine der wenigen, die man gar nicht kürzen kann. Beim Zahlen ist er abzugsfähig, beim Erhalten steuerbar.",
   opts:["nein","ich zahle","ich erhalte","beides"]}

{p1:1, s:"Arbeit", core:1, l:"Erwerbsform", k:"employment", t:"opts", q:"Sind Sie <b>angestellt</b> oder <b>selbständig</b>?",
   why:"Das entscheidet, welche Vorsorge überhaupt für Sie gilt: Angestellte sind ab rund 22 700 Einkommen obligatorisch in der Pensionskasse, Selbständige nicht.",
   opts:["angestellt","selbständig","beides","mehrere Anstellungen","derzeit ohne Erwerb"]}

{s:"Arbeit", g:"arb", opt:1, l:"Reduktionsplan", k:"work_plan", t:"text", q:"Und danach? Beschreiben Sie Ihren <b>Reduktionsplan</b>, falls Sie einen haben.",
   why:"Zum Beispiel: „danach 6 Jahre 50 %, dann Schluss.“ Der Gleitpfad ist oft der eigentliche Plan.",
   skip:"Ich habe noch keinen"}

{s:"Arbeit", g:"arb", core:1, l:"Ist das Ihr Vollpensum?", k:"hours_is_fulltime", t:"opts", q:"Sind diese Stunden Ihr <b>Vollpensum</b> oder schon ein reduziertes?",
   why:"Die Antwort dreht die Gesundheitsrechnung: 50 Stunden als 80 % heisst, das Vollpensum liegt über 60.",
   opts:["mein Vollpensum (100 %)","ein reduziertes Pensum"]}

{p1:1, s:"Arbeit", g:"arb", core:1, l:"Belastbarkeit (0–1)", k:"health", t:"scale", q:"Wie beurteilen Sie Ihre <b>Belastbarkeit</b> — von 0 bis 1?",
   why:"Gesundheit ist im Modell ein Multiplikator direkt auf Ihr Einkommen. 0,85 heisst „gut, aber ich merke etwas“.",
   opts:["0,60","0,70","0,80","0,85","0,90","0,95","1,00"]}

{s:"Weiterbildung", g:"wb", opt:1, l:"Weiterbildung der letzten Jahre", k:"education_recent", t:"text", q:"Haben Sie in den letzten Jahren eine <b>Weiterbildung</b> gemacht?",
   why:"Fachtiefe veraltet: das Modell rechnet mit einer jährlichen Abschreibung auf Wissen, die nur durch Lernen ausgeglichen wird.",
   skip:"Keine", onlyIf:d=>(d.goal_kinds||[]).includes("Weiterbildung oder Umschulung")}

{s:"Weiterbildung", g:"wb", opt:1, l:"Lernstunden pro Woche", k:"education_hours", t:"opts", q:"Wie viele <b>Stunden pro Woche</b> könnten Sie realistisch fürs Lernen aufwenden?",
   why:"Die Rendite auf Lernzeit sättigt bei etwa 20 Stunden pro Woche — darunter zählt jede Stunde deutlich, darüber kaum noch.",
   opts:["keine","1–2","3–5","6–10","mehr als 10"], onlyIf:d=>(d.goal_kinds||[]).includes("Weiterbildung oder Umschulung")}

{s:"Weiterbildung", g:"wb", opt:1, l:"Budget pro Jahr", k:"education_budget", t:"num", q:"Und welches <b>Budget</b> pro Jahr wäre denkbar?",
   why:"Weiterbildungskosten sind in der Schweiz bis zu einem Höchstbetrag steuerlich abzugsfähig — die Netto-Kosten sind also tiefer als der Preis.",
   unit:"CHF / Jahr", min:0, max:200000, skip:"Noch offen", onlyIf:d=>(d.goal_kinds||[]).includes("Weiterbildung oder Umschulung")}

{s:"Vermögen", g:"vors", core:1, opt:1, l:"Einzahlung 3a pro Jahr", k:"pillar3a_contribution", t:"num", q:"Und wie viel zahlen Sie <b>pro Jahr</b> in die Säule 3a ein?",
   why:"Der Höchstbetrag liegt 2026 bei 7 258 Franken für Angestellte mit Pensionskasse. Ohne Angabe rechnet das Modell mit null — das ist bewusst konservativ, macht aber einen Hebel unsichtbar, der Ihnen gehört. Nicht eingezahltes Guthaben lässt sich später nicht nachholen.",
   unit:"CHF", min:0, max:40000, skip:true}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Firmenbeteiligung, Wert", k:"company_value", t:"num", q:"Ihre <b>Firmenbeteiligung</b> — welcher Wert, nach Ihrer eigenen Einschätzung?",
   why:"Eine Schätzung genügt. Wichtiger als die Genauigkeit ist, dass die Position überhaupt in der Bilanz steht.",
   unit:"CHF", min:0, max:500000000, onlyIf:d=>(d.other_kinds||[]).includes("Firmenbeteiligung")}

{s:"Weiteres", g:"weit", dep:"other_kinds", opt:1, l:"Ausschüttung pro Jahr", k:"company_income", t:"num", q:"Bringt die Beteiligung eine <b>laufende Ausschüttung</b>?",
   why:"Ein Ertrag zählt für die Unabhängigkeit, ein Buchwert nicht.", unit:"CHF / Jahr", min:0, max:50000000,
   skip:"Keine Ausschüttung", onlyIf:d=>(d.other_kinds||[]).includes("Firmenbeteiligung")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Gold, Edelmetalle", k:"gold_value", t:"num", q:"<b>Physisches Gold oder Edelmetalle</b> — welcher Wert?",
   why:"Verkäuflich, aber ertraglos: Gold zählt zum Vermögen und nicht zum Einkommen.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Physisches Gold, Edelmetalle")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Ausstehende Darlehen", k:"loans_given", t:"num", q:"<b>Darlehen, die Sie gegeben haben</b> — welcher Betrag steht aus?",
   why:"Ein Guthaben ist es nur, wenn es zurückkommt. Bitte auch nennen, wenn Sie unsicher sind.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Private Darlehen, die ich gegeben habe")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Private Schulden", k:"private_debt", t:"num", q:"<b>Private Schulden</b> — Darlehen von Familie, Gesellschaftern oder Dritten?",
   why:"Diese Positionen fehlen in fast jeder Selbstauskunft und verändern die Bilanz sofort.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Private Schulden, die ich habe")}

{s:"Weiteres", g:"weit", dep:"other_kinds", opt:1, l:"Bedingungen", k:"private_debt_terms", t:"text", q:"Zu welchen <b>Bedingungen</b> — Zins, Fälligkeit, schriftlich?",
   why:"Ein zinsloses Familiendarlehen ohne Fälligkeit ist wirtschaftlich etwas anderes als ein Gesellschafterdarlehen mit Termin.",
   skip:"Keine festen Bedingungen", onlyIf:d=>(d.other_kinds||[]).includes("Private Schulden, die ich habe")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Kunst, Sammlungen, Fahrzeuge", k:"collectibles_value", t:"num", q:"<b>Kunst, Sammlungen, Fahrzeuge</b> — welcher realistische Verkaufswert?",
   why:"Realistisch heisst: was ein Käufer zahlt, nicht was versichert ist.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Kunst, Sammlungen, Fahrzeuge")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Kryptowährungen", k:"crypto_value", t:"num", q:"<b>Kryptowährungen</b> — welcher Wert heute?",
   why:"Liquide, aber mit einem Rückschlagrisiko, das das Modell als eigenständige Position behandeln muss.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Kryptowährungen")}

{s:"Weiteres", g:"weit", core:1, dep:"other_kinds", l:"Lebensversicherung, Rückkaufswert", k:"life_insurance_value", t:"num", q:"<b>Lebensversicherung</b> — welcher Rückkaufswert?",
   why:"Der Rückkaufswert, nicht die Versicherungssumme. Häufig verwechselt, und der Unterschied ist gross.",
   unit:"CHF", min:0, max:100000000, onlyIf:d=>(d.other_kinds||[]).includes("Lebensversicherung mit Rückkaufswert")}

{s:"Risiko", g:"risk", core:1, l:"Verhalten 2008 / 2022", k:"crisis_behaviour", t:"opts", q:"Was haben Sie <b>2008 oder 2022</b> tatsächlich getan, als die Märkte fielen?",
   why:"Verhalten ist aussagekräftiger als jede Selbsteinschätzung.",
   opts:["nichts, ich blieb investiert","nachgekauft","teilweise verkauft","alles verkauft","ich war nicht investiert"]}

{p1:1, s:"Risiko", g:"risk", core:1, l:"Tragbarer Verlust", k:"max_loss_pct", t:"opts", q:"Welcher <b>Verlust auf dem Gesamtvermögen</b> wäre unangenehm, aber tragbar?",
   why:"Diese Grenze geht direkt als Bedingung in die Allokation.",
   opts:["5 %","10 %","15 %","20 %","30 %","weiss ich nicht"]}

{s:"Risiko", g:"risk", core:1, l:"Erwartete Rendite", k:"expected_return_pct", t:"opts", q:"Welche <b>jährliche Rendite</b> erwarten Sie realistisch?",
   why:"Zusammen mit der Verlustgrenze bildet das die Vorgabe, gegen die optimiert wird.",
   opts:["2 %","3 %","4 %","5 %","6 %","8 %","weiss ich nicht"]}

{s:"Feinjustierung", g:"fein", l:"Erholungsstunden pro Woche", k:"rest_hours", t:"opts", q:"Wie viele <b>Stunden pro Woche</b> gehören wirklich Ihnen — Schlaf ausgenommen?",
   why:"Wir haben nach Arbeit gefragt und nie nach Erholung. Im Modell ist das die andere Hälfte der Gesundheitsrechnung, und die Rendite auf Ruhe sättigt: die ersten Stunden zählen am meisten.",
   opts:["kaum welche","5–10","10–20","20–30","mehr als 30"]}

{s:"Feinjustierung", g:"fein", core:1, l:"Rechnen bis Alter", k:"plan_until_age", t:"opts", q:"Bis zu welchem <b>Alter</b> sollen wir rechnen?",
   why:"Die Rentenrechnung ist eine Annuität über einen Zeitraum — ohne diese Zahl müssten wir sie annehmen. Wer bis 100 plant, braucht spürbar mehr als wer bis 85 plant.",
   opts:["85","90","95","100"]}

{s:"Anliegen", g:"schluss", core:1, l:"Ihre Rolle", k:"involvement", t:"opts", q:"Und wie viel möchten Sie <b>selbst</b> tun?",
   why:"Beides ist in Ordnung — es ändert nur, wie das Ergebnis aufbereitet wird.",
   opts:["entscheiden und delegieren","verstehen und mitgestalten"]}
